const files = $items('List Inbox Assets')
  .map(i => i.json || {})
  .filter(f => f.id && f.name);
const queue = $items('Read Existing Queue').map(i => i.json || {});
const cfg = $('Config — Content Studio').first().json || {};
const maxAssetBytes = Number(cfg.maxAssetBytes || 8388608);
const used = new Set();
const driveIdPattern = /drive\.google\.com\/file\/d\/([a-zA-Z0-9_-]{10,})/g;
for (const row of queue) {
  for (const field of ['originalAssetId','Original_Asset_ID']) {
    if (row[field]) used.add(String(row[field]));
  }
  for (const field of ['Source_URLs','Approval_Note','Notes']) {
    const text = String(row[field] || '');
    for (const match of text.matchAll(driveIdPattern)) used.add(match[1]);
  }
}
const supported = new Set(['image/jpeg','image/png','image/webp']);
const candidates = files
  .filter(f => supported.has(String(f.mimeType || '').toLowerCase()))
  .filter(f => !used.has(String(f.id)))
  .sort((a,b)=>new Date(a.modifiedTime||0).getTime()-new Date(b.modifiedTime||0).getTime());
if (!candidates.length) {
  return [{json:{skip:true,reason:'Brak nowych JPG/PNG/WebP w folderze 01_INBOX — BRIEFY I ASSETY.'}}];
}
const f = candidates[0];
const bytes = Number(f.size || 0);
const assetValid = !Number.isFinite(bytes) || bytes <= 0 || bytes <= maxAssetBytes;
const reason = assetValid ? '' : `Plik ${f.name} ma ${bytes} B i przekracza limit ${maxAssetBytes} B. Przeniesiono go do Errors.`;
return [{json:{
  skip:false,assetValid,invalidReason:reason,assetId:f.id,assetName:f.name,
  mimeType:String(f.mimeType||'').toLowerCase(),
  originalUrl:f.webViewLink||`https://drive.google.com/file/d/${f.id}/view`,
  modifiedTime:f.modifiedTime||'',size:f.size||'',maxAssetBytes
}}];

const asset = $('Select One New Image').first().json || {};
const cfg = $('Config — Content Studio').first().json || {};
const maxAssetBytes = Number(cfg.maxAssetBytes || 8388608);
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
if (!buf?.length) throw new Error('Downloaded image is empty.');
if (buf.length > maxAssetBytes) {
  throw new Error(`Downloaded image has ${buf.length} B and exceeds ${maxAssetBytes} B.`);
}
return [{json:{
  ...asset,base64:buf.toString('base64'),sourceBytes:buf.length,
  originalFileName:$binary.data.fileName||asset.assetName,
  mimeType:String($binary.data.mimeType||asset.mimeType||'').toLowerCase()
}}];

const a = $json;
const analysisPrompt = `You are the senior social creative director for VIRYA, a Polish modern/alternative metal band.
Analyze this ORIGINAL image and prepare one publishable social concept.
Return ONLY strict JSON with exactly these fields:
{"asset_summary":"...","quality_score":0,"content_type":"POST","topic":"...","hook":"...","on_screen_text":"","caption_pl":"...","cta":"...","hashtags":"#...","channels":"INSTAGRAM+FACEBOOK","suggested_publish_at":"YYYY-MM-DD HH:mm","alt_text":"...","edit_prompt":"..."}
Constraints:
- caption in natural Polish, max 900 characters;
- no invented achievements, dates, releases, people or endorsements;
- on_screen_text must remain empty;
- edit_prompt may request only conservative photographic processing;
- preserve every face, body, tattoo, instrument, product, logo, clothing detail and background identity;
- never add people, objects, text, logos, flames, smoke, blood or fake stage elements;
- output crop: Instagram portrait 4:5;
- suggested_publish_at: next 14 days in Europe/Warsaw, 18:00-21:00 weekdays or 11:00-20:00 weekends.
Filename: ${a.assetName}`;
return [{json:{...a,analysisPrompt}}];

const src = $('Build Gemini Analysis Request').first().json;
const resp = items[0]?.json || {};
const text = resp.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('') || '{}';
let plan;
try {
  plan = JSON.parse(text.replace(/^```json\s*/i,'').replace(/```$/,'').trim());
} catch (e) {
  throw new Error(`Gemini analysis JSON invalid: ${text.slice(0,600)}`);
}
const required = ['topic','hook','caption_pl','cta','hashtags','channels','suggested_publish_at','alt_text','edit_prompt'];
for (const k of required) if (typeof plan[k] !== 'string') throw new Error(`Missing analysis field: ${k}`);
return [{json:{...src, plan}}];

const p = $json.plan;
const immutable = `IMPORTANT IMMUTABILITY RULES:
Preserve exact identities and anatomy of all people.
Preserve exact tattoos, facial features, hands, fingers, instruments, cables, clothes, brand marks and existing logos.
Do not add, remove or replace any person, object, text, logo, symbol, endorsement or scenery.
Do not create new typography.
Make only photographic finishing changes.`;
const imagePrompt = `${immutable}

Requested edit:
${p.edit_prompt}

Output:
- 4:5 portrait composition
- 1K PNG
- realistic professional music photography
- no text overlays`;
return [{json:{...$json,imagePrompt}}];

const src = $('Build Conservative Image Edit').first().json;
const cfg = $('Config — Content Studio').first().json || {};
const maxGeneratedBytes = Number(cfg.maxGeneratedBytes || 12582912);
const resp = items[0]?.json || {};
const parts = resp.candidates?.[0]?.content?.parts || [];
const img = parts.find(p => p.inlineData?.data || p.inline_data?.data);
const data = img?.inlineData?.data || img?.inline_data?.data;
const mimeType = img?.inlineData?.mimeType || img?.inline_data?.mime_type || 'image/png';
if (!data) throw new Error(`Gemini returned no image. Parts: ${JSON.stringify(parts).slice(0,700)}`);
const generatedBytes = Buffer.from(data, 'base64').length;
if (!generatedBytes || generatedBytes > maxGeneratedBytes) {
  throw new Error(`Generated image has ${generatedBytes} B; allowed maximum is ${maxGeneratedBytes} B.`);
}
const stem = String(src.assetName || 'virya_asset').replace(/\.[^.]+$/,'').replace(/[^a-zA-Z0-9_-]+/g,'_');
const fileName = `${stem}_AI_4x5.png`;
const {base64,analysisPrompt,imagePrompt,...safeSrc}=src;
return [{json:{...safeSrc,derivativeFileName:fileName,generatedBytes},binary:{data:{data,mimeType,fileName,fileExtension:'png'}}}];

